        p1.vida -= p1.ataque - p2.defesa
    } else if {
        p2.vida = 0
    }
}

class S8 {
    ni : string = "kziaaktoo"
    na : string = "imaa rtui"
}

function decode(n46 : S8) : string {
    let t : string = ""

    for (let i : number = 0; i < n46.ni.length; i++) {
            t += n46.ni[i]
            t += n46.na[n46.ni.length - i - 1]
    }

    return t
}

